 #ec .stats{grid-template-columns:repeat(4,1fr);gap:4px;margin-top:22px;padding:14px 6px;border:1px solid var(--line);border-radius:18px;background:rgba(6,18,12,.55);backdrop-filter:blur(8px);text-align:center}
